import ArchipelCore
import Foundation

/// Everything an adapter needs to build the command line for one session.
public struct LaunchContext: Sendable {
    public var archipelSessionID: UUID
    /// The agent's own conversation id: generated by the app for Claude, reported back by Codex.
    public var agentSessionID: String?
    public var hookExecutableURL: URL
    /// A path to the helper that survives app updates and moves, for agents that remember what
    /// they trusted by command line. Nil when the app could not create it, and those hooks are
    /// then left out.
    public var stableHookURL: URL?
    public var socketURL: URL
    /// The folder holding the OpenCode plugin, or nil when the app could not install it.
    public var opencodePluginDirectory: URL?
    /// The plugins from the user's own OpenCode CLI config, as JSON fragments, or nil when that
    /// config could not be read. Injecting ours replaces that list, so without it we must not.
    public var opencodeUserPlugins: [String]?

    public init(
        archipelSessionID: UUID,
        agentSessionID: String?,
        hookExecutableURL: URL,
        stableHookURL: URL? = nil,
        socketURL: URL,
        opencodePluginDirectory: URL? = nil,
        opencodeUserPlugins: [String]? = nil
    ) {
        self.archipelSessionID = archipelSessionID
        self.agentSessionID = agentSessionID
        self.hookExecutableURL = hookExecutableURL
        self.stableHookURL = stableHookURL
        self.socketURL = socketURL
        self.opencodePluginDirectory = opencodePluginDirectory
        self.opencodeUserPlugins = opencodeUserPlugins
    }
}

public struct LaunchCommand: Equatable, Sendable {
    public var executable: String
    public var arguments: [String]
    public var environment: [String: String]

    public init(executable: String, arguments: [String], environment: [String: String]) {
        self.executable = executable
        self.arguments = arguments
        self.environment = environment
    }

    /// Executable and arguments as one string for a POSIX shell. The environment is not
    /// included; it is passed to the terminal separately.
    public var shellCommandLine: String {
        ([executable] + arguments).map(ShellQuoting.quote).joined(separator: " ")
    }
}

public enum ShellQuoting {
    private static let safeCharacters = CharacterSet(
        charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_./=:,+@%"
    )

    public static func quote(_ word: String) -> String {
        if !word.isEmpty, word.unicodeScalars.allSatisfy(safeCharacters.contains) {
            return word
        }
        return "'" + word.replacingOccurrences(of: "'", with: #"'\''"#) + "'"
    }
}

/// A TOML basic string, for values passed through `codex -c key=value`.
func tomlString(_ value: String) -> String {
    var result = "\""
    for scalar in value.unicodeScalars {
        switch scalar {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\t": result += "\\t"
        case "\r": result += "\\r"
        case _ where scalar.value < 0x20 || scalar.value == 0x7F:
            result += String(format: "\\u%04X", scalar.value)
        default: result.unicodeScalars.append(scalar)
        }
    }
    return result + "\""
}

/// What every launched process needs so `archipel-hook` can find the app and the session.
func hookEnvironment(_ context: LaunchContext) -> [String: String] {
    [
        "ARCHIPEL_SESSION_ID": context.archipelSessionID.uuidString,
        "ARCHIPEL_SOCKET": context.socketURL.path,
    ]
}
